function hash(n){n=Math.imul(n^(n>>>16),2246822507);return(n^(n>>>13))>>>0}
function chooseFamily(s){const draw=hash(s.seed^0x7a1d9e5)%100;if(s.race!==0&&typeof SpeciesSociety!=='undefined')return SpeciesSociety.legacyFamily(s,draw);if(draw<4)return'hero';if(draw<8)return'demonKing';if(draw<14&&[9,36].includes(s.race))return'dragonCourt';if(draw<30)return'merchantHouse';if(draw<45)return'exiles';if(draw<60)return'scholars';return'ordinary'}
function ensure(s,newborn=false){
 if(!s.heritage){const familyId=newborn?chooseFamily(s):'ordinary';s.heritage={version:1,familyId,birthRank:s.rank,note:familyById[familyId].description,decorated:false};}
 const h=s.heritage,f=familyById[h.familyId];
 if(newborn&&!h.decorated&&f&&s.age===0&&s.turn===0&&s.household){
  if(f.id!=='ordinary'){
   const previous=s.rank;s.rank=Math.max(previous,f.rank);s.gold+=(s.rank-previous)*9+f.gift;s.family=f.name;s.household.title=f.name;s.household.originNote=f.description;
   const guardians=s.household.members.filter(m=>m.id==='guardian'||m.id.startsWith('parent-'));
   guardians.forEach((m,i)=>{m.adultOccupation=f.parents[i%f.parents.length];m.occupation=m.adultOccupation;});
  }
  h.birthRank=s.rank;h.decorated=true;
 }
 return h;
}
function valid(s){const h=s.heritage;return !h||(h.version===1&&Object.hasOwn(familyById,h.familyId)&&Number.isInteger(h.birthRank)&&h.birthRank>=0&&h.birthRank<CLASSES.length&&typeof h.note==='string'&&h.note.length<1000&&typeof h.decorated==='boolean');}
